func parse(p string) ([]step, error) {
    if len(p) == 0 || p[0] != '$' {
        return nil, fmt.Errorf("jpath: path must start with $: %q", p)
    }
    i := 1
    var steps []step
    for i < len(p) {
        switch {
        case p[i] == '.':
            if i+1 < len(p) && p[i+1] == '.' {
                i += 2
                name, next, err := parseName(p, i)
                if err != nil { return nil, err }
                steps = append(steps, step{kind: stRecurse, name: name})
                i = next
            } else {
                i++
                name, next, err := parseName(p, i)
                if err != nil { return nil, err }
                steps = append(steps, step{kind: stMember, name: name})
                i = next
            }
        case p[i] == '[':
            i++
            if i >= len(p) { return nil, errMalformed }
            if p[i] == '*' {
                if i+1 >= len(p) || p[i+1] != ']' { return nil, errMalformed }
                steps = append(steps, step{kind: stWildcard})
                i += 2
            } else if p[i] == '"' {
                key, next, err := parseQuoted(p, i)
                if err != nil { return nil, err }
                if next >= len(p) || p[next] != ']' { return nil, errMalformed }
                steps = append(steps, step{kind: stMember, name: key})
                i = next + 1
            } else if p[i] == '-' || (p[i] >= '0' && p[i] <= '9') {
                j := i + 1
                neg := false
                if p[i] == '-' { neg = true; j++ }
                if j >= len(p) || p[j] < '0' || p[j] > '9' { return nil, errMalformed }
                v := 0
                for j < len(p) && p[j] >= '0' && p[j] <= '9' {
                    v = v*10 + int(p[j]-'0')
                    j++
                }
                if j >= len(p) || p[j] != ']' { return nil, errMalformed }
                if neg { v = -v }
                steps = append(steps, step{kind: stIndex, idx: v})
                i = j + 1
            } else {
                return nil, fmt.Errorf(...)
            }
        default:
            return nil, fmt.Errorf("jpath: unexpected %q in path %q", p[i], p)
        }
    }
    if steps == nil { steps = []step{} }
    return steps, nil
}
```

