func parseQuoted(p string, i int) (string, int, error) {
    // p[i] == '"'
    var b strings.Builder
    j := i + 1
    for j < len(p) {
        c := p[j]
        if c == '\\' {
            if j+1 >= len(p) { return "", 0, errEsc }
            e := p[j+1]
            if e != '"' && e != '\\' { return "", 0, errEsc }
            b.WriteByte(e)
            j += 2
            continue
        }
        if c == '"' {
            return b.String(), j + 1, nil
        }
        b.WriteByte(c)
        j++
    }
    return "", 0, fmt.Errorf("jpath: unterminated quoted key")
}
